{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Ketoprofen, a benzoyl aryl carboxylic acid NSAID, has an absolute oral bioavailability of at least 92% in humans when oral 100 mg is compared with IV data; this direct high-F measurement transfers to the query because the query shares the benzoyl ketone and ionizable carboxylic acid motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiaprofenic acid, a benzoyl thiophene carboxylic acid, is almost completely absorbed with oral bioavailability about 90-100% in humans, supporting high oral bioavailability for the structurally analogous benzoyl carboxylic acid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "R-ketoprofen absolute bioavailability was 84.5 ± 20.6% in healthy subjects, providing additional direct evidence that this class of acidic benzoyl carboxylic acids achieves high oral bioavailability despite ionization at physiological pH.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an acidic benzoyl-substituted bicyclic carboxylic acid (ketorolac-like). The strongest transferable experimental evidence comes from ketoprofen and tiaprofenic acid, both benzoyl carboxylic acids with absolute oral bioavailability ≥84-100% in humans. These direct measurements outweigh the uncertain physicochemical prior and support a high probability of F ≥20%. Low-bioavailability analogues such as indoramin, fentanyl, and cocaine are structurally dissimilar basic/lipophilic drugs with different first-pass and transporter liabilities and do not transfer to this acidic NSAID-like query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself was provided; prediction relies on close structural analogues.",
    "Morgan similarity scores for the supporting analogues are low (0.26-0.27), so quantitative transferability is uncertain, although the shared benzoyl/carboxylic acid pharmacophore is chemically relevant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

